package com.pabonaki.model;import org.springframework.data.annotation.Id;import org.springframework.data.mongodb.core.index.Indexed;import org.springframework.data.mongodb.core.mapping.Document;import java.time.Instant;import java.util.List;@Document("orders")public class Order{@Id private String id;@Indexed(unique=true)private String orderNumber;@Indexed private String userId;private String customerName,email,phone,address,deliveryArea,paymentMethod="COD",paymentStatus="UNPAID",transactionId,courierTrackingId,courierStatus,status="PENDING";private double subtotal,deliveryCharge,total;private List<Item> items;private Instant createdAt=Instant.now(),updatedAt=Instant.now();public static class Item{private String productId,sku,name,imageUrl;private double unitPrice;private int quantity;public String getProductId(){return productId;}public void setProductId(String v){productId=v;}public String getSku(){return sku;}public void setSku(String v){sku=v;}public String getName(){return name;}public void setName(String v){name=v;}public String getImageUrl(){return imageUrl;}public void setImageUrl(String v){imageUrl=v;}public double getUnitPrice(){return unitPrice;}public void setUnitPrice(double v){unitPrice=v;}public int getQuantity(){return quantity;}public void setQuantity(int v){quantity=v;}}public String getId(){return id;}public void setId(String v){id=v;}public String getOrderNumber(){return orderNumber;}public void setOrderNumber(String v){orderNumber=v;}public String getUserId(){return userId;}public void setUserId(String v){userId=v;}public String getCustomerName(){return customerName;}public void setCustomerName(String v){customerName=v;}public String getEmail(){return email;}public void setEmail(String v){email=v;}public String getPhone(){return phone;}public void setPhone(String v){phone=v;}public String getAddress(){return address;}public void setAddress(String v){address=v;}public String getDeliveryArea(){return deliveryArea;}public void setDeliveryArea(String v){deliveryArea=v;}public String getPaymentMethod(){return paymentMethod;}public void setPaymentMethod(String v){paymentMethod=v;}public String getPaymentStatus(){return paymentStatus;}public void setPaymentStatus(String v){paymentStatus=v;}public String getTransactionId(){return transactionId;}public void setTransactionId(String v){transactionId=v;}public String getCourierTrackingId(){return courierTrackingId;}public void setCourierTrackingId(String v){courierTrackingId=v;}public String getCourierStatus(){return courierStatus;}public void setCourierStatus(String v){courierStatus=v;}public String getStatus(){return status;}public void setStatus(String v){status=v;}public double getSubtotal(){return subtotal;}public void setSubtotal(double v){subtotal=v;}public double getDeliveryCharge(){return deliveryCharge;}public void setDeliveryCharge(double v){deliveryCharge=v;}public double getTotal(){return total;}public void setTotal(double v){total=v;}public List<Item> getItems(){return items;}public void setItems(List<Item> v){items=v;}public Instant getCreatedAt(){return createdAt;}public Instant getUpdatedAt(){return updatedAt;}public void setUpdatedAt(Instant v){updatedAt=v;}}